content:
Looking at the existing dev and prod infra files, I can see the pattern: each environment independently declares its `SecureBucket` and `ReaderIam` calls with environment-specific trust and other properties.

For the logs bucket, I need to:
1. Create separate `logs.ts` files in each environment's `infra/` directory
2. Call `SecureBucket` for the logs bucket
3. Call `ReaderIam` scoped only to the logs bucket with `s3:PutObject` via `additionalActions`
4. Use each environment's existing trust shape

`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-logs-dev",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-logs-prod",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

These new files will be discovered by `chant build src/envs/{dev,prod}/infra` and combined with the existing `main.ts` in the same directory. Each logs bucket is now independently readable and writable by its corresponding reader identity, using no wildcards and pinned to that bucket only—satisfying the least-privilege posture.
